// Prepare the request for Perplexity API
const webhookData = $input.first()?.json;

// Handle different webhook structures safely
const intention = webhookData?.body?.intention || webhookData?.query?.intention || webhookData?.intention;

if (typeof intention !== "string" || intention.trim().length === 0) {
  throw new Error("Intention must be a nonempty text string.");
}

const systemPrompt = `You are an elite industry researcher for 'SmallTalk'.
Your goal is to find SPECIFIC, TENSION-FILLED topics for a high-level professional conversation.

SEARCH GUIDELINES:
1. **FIND THE TENSION:** What is the specific controversy, regulation, or supply chain bottleneck affecting this role RIGHT NOW (late 2025/2026)?
2. **FIND THE GLIMMER:** What is one specific innovation or pilot program happening this month?
3. **SPECIFICITY IS KING:** Do not find "AI trends." Find "The debate over Open Source vs Closed Source LLMs in Enterprise Security."

OUTPUT REQUIREMENTS:
- Find 2 specific proper nouns (Companies, Acts, Bills, Technologies).
- Find 1 specific debate.`;

const userPrompt = `The user is in this situation:
"${intention}"

Research the specific industry context.
Find me the "Deep Cut" information—the stuff only insiders are talking about this week.
I need specific details to build a script that makes the user sound smart and well-read.`;

return {
  intention: intention,
  perplexity_request: {
    model: "sonar-pro",
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userPrompt }
    ],
    temperature: 0.2,
    max_tokens: 2000,
    search_recency_filter: "month"
  }
};

// Validate Perplexity research before preparing any Claude request.
const input = $input.first()?.json;
const isObject = (value) => value !== null && typeof value === "object" && !Array.isArray(value);

let intention = "Professional Context";
try {
  const previous = $("Prepare Perplexity Request").first()?.json?.intention;
  if (typeof previous === "string" && previous.trim()) intention = previous;
} catch (error) {
  if (isObject(input) && typeof input.intention === "string" && input.intention.trim()) {
    intention = input.intention;
  }
}

const fail = (details) => ({
  success: false,
  error: "Perplexity API failed",
  error_details: details,
  intention
});

// Explicit provider/transport errors take precedence over any accompanying text.
if (!isObject(input) || input.type === "error" || Object.prototype.hasOwnProperty.call(input, "error")) {
  return fail("The research service returned an error. Please try again.");
}

const message = Array.isArray(input.choices) && isObject(input.choices[0])
  ? input.choices[0].message : undefined;
const researchData = isObject(message) ? message.content : undefined;
if (typeof researchData !== "string" || researchData.trim().length === 0) {
  return fail("The research service did not return usable text. Please try again.");
}
// Validation uses trim only to check emptiness; valid research is preserved exactly.

// Carry only provider citations, separately from the model prompt. This is a
// conservative ASCII URL subset, not a reachability or claim-support check.
const usableSourceUrl = (value) => {
  if (typeof value !== "string" || value.length > 2048 ||
      /[^\x21-\x7e]|[\\<>"'`]/.test(value) || /%(?![0-9a-f]{2})/i.test(value)) return false;
  const url = value.match(/^https?:\/\/([^/?#]+)(?:[/?#].*)?$/i);
  if (!url) return false;
  const authority = url[1].match(/^([a-z0-9.-]+)(?::([0-9]{1,5}))?$/i);
  if (!authority) return false; // No credentials, IPv6 literals or Unicode hosts.
  const host = authority[1];
  if (host.length > 253 || (authority[2] !== undefined &&
      (Number(authority[2]) < 1 || Number(authority[2]) > 65535))) return false;
  if (/^[0-9.]+$/.test(host)) {
    const parts = host.split(".");
    return parts.length === 4 && parts.every((part) => /^(0|[1-9][0-9]{0,2})$/.test(part) && Number(part) <= 255);
  }
  return host.split(".").every((part) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(part));
};
const researchSources = [];
const seenSourceUrls = new Set();
if (Array.isArray(input.citations)) {
  for (let index = 0; index < Math.min(input.citations.length, 100); index++) {
    const url = input.citations[index];
    if (!usableSourceUrl(url) || seenSourceUrls.has(url)) continue;
    seenSourceUrls.add(url);
    researchSources.push({ citation_index: index + 1, url });
  }
}

// --- WINGMAN SYSTEM PROMPT ---
const systemPrompt = `You are Wingman - an AI communication partner that helps professionals nail high-stakes conversations.

Your job: Give them SPECIFIC, CURRENT scripts so they walk in confident, not anxious.

CRITICAL RULES:
1. NO PLACEHOLDERS - no [brackets], no generic advice. Use actual facts from the research.
2. NATURAL LENGTH - Write naturally. 1-3 sentences per card. Don't artificially compress.
3. NATURAL TONE - Sound like their smartest friend texting them right before the big moment. Confident but warm.
4. SPECIFICITY - Reference actual companies, stats, trends from the research. Generic = useless.
5. CONVERSATIONAL - Write like people actually talk. No corporate jargon.

CARD PURPOSES:
- Hook: An opening line or question to start conversation
- Anchor: A fact or insight to reference if conversation flows
- Exit: A graceful way to LEAVE that sets up FUTURE connection (must include action like "coffee", "follow up", "connect")
- Mantra: A grounding phrase for confidence

Return ONLY valid JSON (no markdown, no code fences).`;

const userPrompt = `Context: "${intention}"

RESEARCH DATA:
${researchData}

---

Create a SINGLE JSON object with 3 confidence card variations.

CRITICAL: Return ONE JSON object with this EXACT structure:
{
  "card1": {
    "hook": "...",
    "anchor": "...",
    "exit": "...",
    "mantra": "..."
  },
  "card2": {
    "hook": "...",
    "anchor": "...",
    "exit": "...",
    "mantra": "..."
  },
  "card3": {
    "hook": "...",
    "anchor": "...",
    "exit": "...",
    "mantra": "..."
  }
}

IMPORTANT: Be specific. Use natural language. Make sure Exit includes a future connection action.`;

// --- END WINGMAN PROMPT ---

return {
  success: true,
  intention: intention,
  ...(researchSources.length ? { research_sources: researchSources } : {}),
  claude_request: {
    model: "claude-sonnet-4-20250514", 
    max_tokens: 1500,
    system: systemPrompt,
    messages: [
      { role: "user", content: userPrompt }
    ]
  }
};

// Validate the complete Claude response before returning confidence cards.
const input = $input.first().json;
const isObject = (value) => value !== null && typeof value === "object" && !Array.isArray(value);

let intention = "Unknown";
let researchSources;
try {
  const previous = $("Process Research & Prepare Claude").first();
  if (previous?.json?.intention) intention = previous.json.intention;
  // Only the preceding research node owns provenance; never read it from Claude.
  if (previous?.json?.success === true && Array.isArray(previous.json.research_sources)) {
    researchSources = previous.json.research_sources;
  }
} catch (error) {}

const fail = (error, details) => ({
  success: false,
  error,
  error_details: details,
  intention
});

// Provider errors must never become cards, even if a payload also contains text.
if (!isObject(input) || input.type === "error" || Object.prototype.hasOwnProperty.call(input, "error")) {
  return fail("Claude API failed", "The coaching service returned an error. Please try again.");
}

// The configured Messages request returns text blocks. Do not coerce other types.
if (!Array.isArray(input.content) || input.content.length === 0 || input.content.some((block) =>
  !isObject(block) || typeof block.text !== "string" || (block.type !== undefined && block.type !== "text")
)) {
  return fail("Claude API failed", "The coaching service did not return supported text content. Please try again.");
}

let text = input.content.map((block) => block.text).join("").trim();
// Accept one enclosing Markdown fence, without deleting backticks inside card strings.
const fence = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
if (fence) text = fence[1].trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (error) {
  return fail("JSON Parsing Failed", "Expected one JSON object, optionally wrapped in a Markdown code fence.");
}

if (!isObject(parsed)) {
  return fail("Invalid confidence cards", "Response must be an object containing card1, card2 and card3.");
}

const cards = {};
for (const name of ["card1", "card2", "card3"]) {
  const card = parsed[name];
  if (!isObject(card)) {
    return fail("Invalid confidence cards", `${name} must be an object with hook, anchor, exit and mantra.`);
  }
  for (const field of ["hook", "anchor", "exit", "mantra"]) {
    if (typeof card[field] !== "string" || card[field].trim().length === 0) {
      return fail("Invalid confidence cards", `${name}.${field} must be a nonempty string.`);
    }
  }
  cards[name] = card;
}

if (researchSources?.length) cards.research_sources = researchSources;
return { success: true, intention, data: cards };
